// Standardized case data format for investigation system
// Can be generated by AI or filled manually

export interface CaseDataFormat {
  case: {
    title: string
    description: string
  }
  suspects: Array<{
    name: string
    profile: string
  }>
  evidence: Array<{
    type: "witness_statement" | "forensic_report" | "cctv_log" | "financial_record" | "email_message" | "location_report"
    content: string
  }>
}

