// Standardized format instructions for AI generation:
export const generationPrompt = `
Generate a detective case following this exact JSON structure:

{
  "case": {
    "title": "Case Title",
    "description": "2-3 sentence description of the case"
  },
  "suspects": [
    {
      "name": "Suspect name",
      "profile": "Background, motive, relationship to victim"
    }
    // 4-5 suspects total
  ],
  "evidence": [
    {
      "type": "witness_statement|forensic_report|cctv_log|financial_record|email_message|location_report",
      "content": "Evidence content - specific details, quotes, times, locations"
    }
    // 20-30 evidence items total
    // Include contradictions, timeline gaps, hidden relationships
  ]
}

Requirements:
- Create realistic, self-contained criminal investigation scenario
- Include timeline conflicts and contradictions
- Evidence should reference specific times and names
- Some suspects should have multiple conflicting testimonies
- Include both incriminating and exonerating evidence
- Financial, communication, and surveillance evidence should interweave
- Hidden relationships between suspects and victim recommended
- Evidence should support critical reasoning, not simple pattern matching
`
